package com.neversion.api.user.application.port.out;

import java.util.Optional;

import com.neversion.api.user.domain.model.enums.UserRole;

public interface AuthServicePort {

    /**
     * Creates a user in the auth service using the Admin API, injecting the specified role.
     *
     * @param email    The user's email address
     * @param password The user's chosen password
     * @param role     The role to assign (e.g., VENDOR, CLIENT)
     * @return The UUID generated by the auth service (externalId)
     * @throws RuntimeException if the user creation fails
     */
    String createUser(String email, String password, UserRole role);

    /**
     * Resolves the email address for an existing auth user.
     *
     * @param externalId Auth user ID
     * @return email address when user is found
     */
    Optional<String> findEmailByExternalId(String externalId);
}
